import{_ as r,c as a,o as s,ah as i,j as e,a as n}from"./chunks/framework.9BEr0c9W.js";const d="/Qonnectra-docs/pr-15/images/manual/teil-a/conduit_search.jpg",l="/Qonnectra-docs/pr-15/images/manual/teil-a/conduit_search_columns.jpg",h="/Qonnectra-docs/pr-15/images/manual/teil-a/map_opacity.jpg",o="/Qonnectra-docs/pr-15/images/manual/teil-a/map_legend.jpg",c="/Qonnectra-docs/pr-15/images/manual/teil-a/map_legend_actions.jpg",u="/Qonnectra-docs/pr-15/images/manual/teil-a/map_address_detail.jpg",m="/Qonnectra-docs/pr-15/images/manual/teil-a/map_address_detail_select.jpg",b="/Qonnectra-docs/pr-15/images/manual/teil-a/map_search.jpg",g="/Qonnectra-docs/pr-15/images/manual/teil-a/map_search_flow.jpg",p="/Qonnectra-docs/pr-15/videos/map_measure.webm",f="/Qonnectra-docs/pr-15/videos/map_attachment.webm",A=JSON.parse('{"title":"3. Wiederkehrende Bedienelemente","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.md","filePath":"manual/teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.md"}'),k={name:"manual/teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.md"};function S(w,t,z,_,v,D){return s(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="_3-wiederkehrende-bedienelemente" tabindex="-1">3. Wiederkehrende Bedienelemente <a class="header-anchor" href="#_3-wiederkehrende-bedienelemente" aria-label="Permalink to &quot;3. Wiederkehrende Bedienelemente&quot;">​</a></h1><p>Einige Bedienelemente von Qonnectra tauchen in mehreren Ansichten unverändert auf: das Kartenfenster mit seiner Legende, die Objektsuche, die Info-Box am rechten Rand und die Anhänge. Dieses Kapitel beschreibt sie einmal; die Kapitel zu den einzelnen Menüpunkten verweisen darauf und nennen nur noch, was dort davon abweicht.</p><h2 id="_3-1-tabellen-suche-spaltenfilter-sortierung-seitenwechsel" tabindex="-1">3.1 Tabellen: Suche, Spaltenfilter, Sortierung, Seitenwechsel <a class="header-anchor" href="#_3-1-tabellen-suche-spaltenfilter-sortierung-seitenwechsel" aria-label="Permalink to &quot;3.1 Tabellen: Suche, Spaltenfilter, Sortierung, Seitenwechsel&quot;">​</a></h2><p>Die Rohrverwaltung, die Adressen und die Leitungsauskunft führen ihren Bestand in einer Tabelle auf. Diese drei Tabellen sind gleich aufgebaut und werden gleich bedient. Ein Klick auf eine Zeile öffnet den zugehörigen Datensatz: in der Rohrverwaltung in der Info-Box am rechten Rand, bei den Adressen und der Leitungsauskunft auf einer eigenen Seite.</p><p><strong>Sortieren</strong></p><p>Ein Klick auf eine Spaltenüberschrift sortiert die Tabelle nach dieser Spalte: der erste Klick aufsteigend, der zweite absteigend, der dritte hebt die Sortierung wieder auf. Das Symbol rechts neben der Überschrift zeigt, wonach gerade sortiert wird.</p><p><strong>Suchfeld über der Tabelle</strong></p><p>Das Suchfeld über der Tabelle durchsucht den gesamten Bestand des Projekts. Geben Sie einen Suchbegriff ein und drücken Sie Enter oder klicken Sie auf das Lupensymbol. Die Tabelle beginnt danach wieder bei Seite 1 und enthält nur noch die passenden Datensätze; die Gesamtzahl unter der Tabelle passt sich an. Um wieder alle Datensätze zu sehen, leeren Sie das Feld und lösen die Suche erneut aus.</p><p><img src="'+d+'" alt="Screenshot Rohrverwaltung mit Hervorhebung des Suchfeldes oben; die Tabelle darunter zeigt nur noch die drei Treffer" data-zoomable="true"></p><p><strong>Suchfelder unter den Spaltenüberschriften</strong></p><p>Unter jeder Spaltenüberschrift liegt ein eigenes Suchfeld. Diese Felder arbeiten bereits beim Tippen, ohne Enter, und lassen sich miteinander kombinieren: Ein Datensatz bleibt nur stehen, wenn er zu allen ausgefüllten Feldern passt. Zum Aufheben leeren Sie die Felder wieder.</p><p><img src="'+l+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Suchfelder unter den Spaltenüberschriften" data-zoomable="true"></p><p><strong>Seitenwechsel</strong></p><p>Eine Seite umfasst 50 Datensätze. Unter der Tabelle stehen links die Gesamtzahl, z. B. „123 Ergebnisse“, und rechts die Seitenauswahl mit den Pfeilen für die vorherige und die nächste Seite. Bleibt kein Datensatz übrig, erscheint anstelle der Zeilen „Keine Ergebnisse gefunden“.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Sortierung und Spaltenfilter wirken nur auf die angezeigte Seite. Bei mehr als einer Seite bleibt ein Datensatz von einer anderen Seite außen vor – auch wenn er alphabetisch an erster Stelle stünde. Für den gesamten Bestand ist das Suchfeld über der Tabelle zuständig; nur dadurch ändert sich auch die Gesamtzahl.</p></div><p>Welche Spalten eine Tabelle hat, nennt das Kapitel zu der jeweiligen Ansicht.</p><h2 id="_3-2-auswahllisten-und-kombinationsfelder" tabindex="-1">3.2 Auswahllisten und Kombinationsfelder <a class="header-anchor" href="#_3-2-auswahllisten-und-kombinationsfelder" aria-label="Permalink to &quot;3.2 Auswahllisten und Kombinationsfelder&quot;">​</a></h2><p>Werte, die aus einer festen Liste stammen – Rohrtyp, Status, Netzebene, Firmen, Kennzeichen –, wählen Sie in einem <strong>Kombinationsfeld</strong>: einem Eingabefeld mit einem Pfeil am rechten Rand. Über den Pfeil öffnen Sie die vollständige Liste, über eine Eingabe in das Feld schränken Sie sie ein. Das bekannteste davon ist die Projektauswahl in der Kopfzeile, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>.</p><p>Ihre Eingabe muss nicht am Anfang eines Eintrags stehen, und die Suche verzeiht Tippfehler: Auch eine ungefähre Schreibweise führt in der Regel noch zum passenden Eintrag.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Findet Ihre Eingabe keinen Eintrag, bleibt die Liste nicht leer, sondern zeigt wieder alle Einträge. Eine volle Liste bedeutet also nicht, dass Ihre Eingabe gepasst hat.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Eingabe allein wählt nichts aus – erst der Klick auf einen Eintrag übernimmt den Wert in das Feld.</p></div><p>Sind für ein Feld überhaupt keine Werte hinterlegt, erscheint anstelle des Feldes der Hinweis „Keine Daten verfügbar“. Die Auswahlwerte sind Stammdaten und werden im Administrationsbereich gepflegt, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>.</p><h2 id="_3-3-das-kartenfenster" tabindex="-1">3.3 Das Kartenfenster <a class="header-anchor" href="#_3-3-das-kartenfenster" aria-label="Permalink to &quot;3.3 Das Kartenfenster&quot;">​</a></h2><p>Ein Kartenfenster gibt es in der Karte selbst sowie in der Rohrzuordnung, den Mikrorohren, der Störungsanalyse, der Leitungsauskunft und der Wertermittlung. In diesen Ansichten verhält es sich gleich; dieser Abschnitt beschreibt es.</p><p>Das Netzschema selbst ist ein Diagramm und enthält keine Karte. Ein Kartenfenster erscheint dort erst im Fenster „Kabel-Mikrorohr Verknüpfung“: Klicken Sie ein Kabel an und öffnen Sie es in der Info-Box über den Reiter „Aktionen“ mit „Mit Mikrorohr verbinden“, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Nachverdichtung und die Detailansicht einer Adresse enthalten ebenfalls eine Karte, dort aber in einer verkleinerten Form ohne Suche, Legende und Transparenzregler. Sie dient nur der Lagekontrolle.</p><p>Der Faserweg zeigt neben seinem Ergebnis eine eigene Karte, die nicht das hier beschriebene Kartenfenster ist: Sie zeichnet ausschließlich den ermittelten Weg, und Suche, Legende, Transparenzregler und Messen fehlen. Ein Klick wählt darin ein Element des Wegs aus. Beschrieben wird sie in Kapitel <a href="./15-faserweg.html">Faserweg</a>.</p></div><p>Mit dem Mausrad oder dem Touchpad zoomen Sie in die Karte hinein und heraus, mit gedrückter linker Maustaste verschieben Sie den Kartenausschnitt.</p><p>Links unten finden Sie den Regler „Transparenz“, mit dem Sie die <strong>Transparenz</strong> der Hintergrundkarte anpassen können. Dies ist hilfreich, um Netzdaten besser sichtbar zu machen.</p><p><img src="'+h+'" alt="Screenshot Karte mit Hervorhebung des Schiebereglers für die Transparenz der Karte" data-zoomable="true"></p><p>Auf der rechten Seite befindet sich die <strong>interaktive Legende</strong> („Layer“-Menü) mit den Einträgen „Adresse“, „Netzknoten“, „Trasse“, „Rohr“, „Gebiet“ und „OpenStreetMap“. Über die Symbole an den Einträgen können Sie:</p><ul><li>Objektarten (Layer) ein- oder ausblenden</li><li>Beschriftungen anzeigen oder verbergen</li><li>mit „Auf Ausdehnung zoomen“ die Ansicht auf alle Objekte eines Layers ausrichten</li><li>die Einträge „Netzknoten“ und „Gebiet“ über den kleinen Pfeil links aufklappen und die einzelnen Typen getrennt schalten</li><li>die Hintergrundkarte über den Eintrag „OpenStreetMap“ ausblenden oder in den Dunkelmodus wechseln</li></ul><p>Nicht jeder Eintrag bietet alle Möglichkeiten: Beim Eintrag „Rohr“ steht ausschließlich „Leitungsbeschriftungen anzeigen“ zur Verfügung.</p><p>Der Eintrag „Trasse“ lässt sich zusätzlich aufklappen, sobald Sie unter „Einstellungen“ die „Trassen-Darstellung“ von „Einzelne Farbe“ auf „Nach Oberfläche“ oder „Nach Bauart“ umgestellt haben. Sie schalten dann die einzelnen Oberflächen oder Bauarten getrennt, siehe Kapitel <a href="./17-einstellungen.html">Einstellungen</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Hat Ihre Administration für das Projekt externe Kartendienste (WMS) hinterlegt, stehen diese unterhalb der aufgeführten Einträge als eigene, aufklappbare Gruppe. Das Einrichten beschreibt Kapitel <a href="./../teil-b-betrieb-admin-qgis/27-qgis-server-und-kartendienste.html">QGIS-Server und Kartendienste</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beschriftungen werden erst ab einer ausreichenden Zoomstufe eingeblendet. Wenn sich nach dem Einschalten nichts sichtbar ändert, zoomen Sie weiter in die Karte hinein.</p></div><p class="img-row"><img src="'+o+'" alt="Screenshot Karte mit Hervorhebung der Legende oben rechts" data-zoomable="true"><img src="'+c+'" alt="Vier Screenshots der Karte mit verschiedenen Einstellungen in der Legende" data-zoomable="true"></p><p>Mit „Auf Ausdehnung zoomen“ beim Eintrag „Adresse“ gelangen Sie in den Bereich, in dem für das gewählte Projekt Daten vorhanden sind.</p><p class="img-row"><img src="'+u+'" alt="Screenshot Karte mit Hervorhebung des Layers Adresse in der Legende rechts oben" data-zoomable="true"><img src="'+m+'" alt="Screenshot Karte nach dem Zoom auf die Ausdehnung des Layers Adresse" data-zoomable="true"></p><p><strong>Objekte anklicken</strong></p><p>Ein Klick in die Karte wählt das Objekt darunter aus. Zwei Eigenheiten des Netzbestands machen das schwerer, als es klingt: Trassen sind nur wenige Pixel breit und laufen an Netzknoten zusammen, und die Fläche eines Projektgebiets liegt unter dem gesamten Netz. Innerhalb eines Gebiets trifft ein Klick deshalb leicht dessen Fläche, die daraufhin die ganze Karte in der Auswahlfarbe überdeckt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Treffen Sie nicht das gewünschte Objekt, zoomen Sie weiter in die Karte hinein oder blenden Sie den Layer „Gebiet“ in der Legende vorübergehend aus. In den verkleinerten Karten der Nachverdichtung und der Adressdetails ist das nicht möglich, weil sie keine Legende haben.</p></div><h2 id="_3-4-objekte-in-der-karte-suchen" tabindex="-1">3.4 Objekte in der Karte suchen <a class="header-anchor" href="#_3-4-objekte-in-der-karte-suchen" aria-label="Permalink to &quot;3.4 Objekte in der Karte suchen&quot;">​</a></h2><p>Oben links im Kartenfenster befindet sich eine <strong>Suchfunktion</strong>. Hier können Sie gezielt nach Adressen, Netzknoten, Trassen, Rohren und Gebieten suchen.</p><p><img src="'+b+'" alt="Screenshot Karte mit Hervorhebung des Suchfeldes oben links" data-zoomable="true"></p><p>Dazu gehen Sie folgendermaßen vor:</p><ol><li>Geben Sie einen Begriff oder einen Teil davon in das Suchfeld ein.</li><li>Drücken Sie Enter oder klicken Sie auf das Lupensymbol.</li><li>Die Trefferliste öffnet sich unterhalb des Suchfeldes und nennt die Anzahl der Treffer.</li><li>Jeder Treffer ist mit seiner Objektart gekennzeichnet.</li><li>Ab zehn Treffern erscheint im Kopf der Liste das Feld „Filtern...“, mit dem Sie die Liste weiter einschränken.</li><li>Klicken Sie auf einen Treffer: Die Karte springt an die passende Stelle und das Objekt blinkt dreimal auf.</li></ol><p><img src="'+g+'" alt="Vier Screenshots des Suchablaufs in der Karte, nummeriert von 1 bis 6" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Treffer öffnet die Info-Box <strong>nicht</strong>. Die Karte springt nur an die passende Stelle; klicken Sie das Objekt anschließend in der Karte an, um die Details zu sehen, siehe Kapitel <a href="./05-karte.html">Karte</a>.</p></div><h2 id="_3-5-strecke-und-flache-messen" tabindex="-1">3.5 Strecke und Fläche messen <a class="header-anchor" href="#_3-5-strecke-und-flache-messen" aria-label="Permalink to &quot;3.5 Strecke und Fläche messen&quot;">​</a></h2><p>In jedem Kartenfenster können Sie Entfernungen und Flächen abgreifen, ohne etwas an den Daten zu ändern. Klicken Sie mit der rechten Maustaste in die Karte; das Kontextmenü bietet „Strecke messen“ und „Fläche messen“.</p><ol><li>Wählen Sie „Strecke messen“ oder „Fläche messen“. Der Mauszeiger wird zum Fadenkreuz.</li><li>Klicken Sie nacheinander die Punkte der Strecke oder die Eckpunkte der Fläche an.</li><li>Während des Zeichnens nennt eine Beschriftung an der Zeichnung fortlaufend den aktuellen Wert.</li><li>Ein Doppelklick beendet die Zeichnung; der Wert bleibt daran stehen.</li></ol><p>Strecken unter 100 m stehen in Metern, längere in Kilometern; Flächen unter 10.000 m² in Quadratmetern, größere in Quadratkilometern – jeweils auf zwei Nachkommastellen gerundet.</p><p>Zum Aufräumen klicken Sie erneut mit der rechten Maustaste und wählen „Messung beenden“. Das entfernt die Zeichnung und schaltet zurück in die normale Bedienung.</p>',53),e("p",null,[e("video",{src:p,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/map_measure.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),i('<div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein Klick während einer Messung setzt nicht nur einen Messpunkt, sondern wählt zugleich das Objekt darunter aus und öffnet die Info-Box – mit den Folgen, die Abschnitt <a href="#_3-3-das-kartenfenster">Das Kartenfenster</a> unter „Objekte anklicken“ beschreibt. Blenden Sie den Layer „Gebiet“ aus, bevor Sie in einem Projektgebiet messen.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Es gibt immer nur eine Messung: Eine neue ersetzt die vorherige. Messergebnisse werden nicht gespeichert und sind in keinem Export enthalten.</p></div><h2 id="_3-6-die-info-box-mit-ihren-reitern" tabindex="-1">3.6 Die Info-Box mit ihren Reitern <a class="header-anchor" href="#_3-6-die-info-box-mit-ihren-reitern" aria-label="Permalink to &quot;3.6 Die Info-Box mit ihren Reitern&quot;">​</a></h2><p>Wenn Sie ein Objekt auswählen, öffnet sich am rechten Rand die <strong>Info-Box</strong>. Sie überlagert die Ansicht, ohne den Kartenausschnitt oder die Tabelle darunter zu verändern. Welche Reiter sie enthält, hängt von der Objektart ab; „Eigenschaften“ und „Anhänge“ gibt es immer.</p><p>Die Angaben im Reiter „Eigenschaften“ sind je nach Ansicht nur zur Information oder bearbeitbar – in der Karte lesen Sie sie, in der Rohrverwaltung ändern Sie sie. Im Reiter „Aktionen“ finden Sie weiterführende Ansichten zum ausgewählten Objekt. Der Reiter „Anhänge“ ist überall bearbeitbar, siehe Abschnitt <a href="#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a>.</p><p>Ist die Info-Box zu schmal, ziehen Sie sie am linken Rand über den Griff „Größe der Seitenleiste ändern“ breiter. Über das Kreuz „Seitenleiste schließen“ schließen Sie sie.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Anwendung nennt die Info-Box in diesen beiden Beschriftungen „Seitenleiste“ – dasselbe Wort, das sie in „Seitenleiste anpassen“ für die Navigationsleiste am linken Rand verwendet (siehe Abschnitt <a href="./01-erste-schritte.html#_1-5-navigationsleiste-anpassen">Navigationsleiste anpassen</a>). Gemeint sind zwei verschiedene Dinge; dieses Handbuch nennt die Anzeige am rechten Rand durchgehend Info-Box.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die eingestellte Breite gilt für alle Ansichten mit einer Info-Box, nicht nur für die, in der Sie sie geändert haben.</p></div><h2 id="_3-7-anhange-hochladen-ansehen-und-loschen" tabindex="-1">3.7 Anhänge hochladen, ansehen und löschen <a class="header-anchor" href="#_3-7-anhange-hochladen-ansehen-und-loschen" aria-label="Permalink to &quot;3.7 Anhänge hochladen, ansehen und löschen&quot;">​</a></h2><p>Zu Kartenobjekten, Rohren und Adressen können Sie Dateien ablegen; der Reiter „Anhänge“ steht deshalb bei allen diesen Objektarten zur Verfügung. Zum Hinzufügen klicken Sie im Bereich „Dateien hochladen“ auf „Dateien auswählen“ oder ziehen die Datei auf die Fläche „Dateien auswählen oder hierher ziehen“. Die maximale Dateigröße beträgt 50 MB.</p><p>Vorhandene Dateien stehen darunter im Bereich „Hochgeladene Dateien“, zusammengefasst in Ordnern mit der Anzahl dahinter, z. B. „documents (1)“. Die Ordnernamen kommen aus der Ablagestruktur und sind deshalb englisch. Klicken Sie auf einen Ordner, um ihn aufzuklappen – erst dann werden die einzelnen Dateien sichtbar. Zeigen Sie anschließend mit der Maus auf eine Datei, erscheinen rechts neben dem Dateinamen die Schaltflächen „Herunterladen“, „Umbenennen“ und „Datei löschen“; beim Löschen bestätigen Sie die Rückfrage.</p><p>Bei vielen Dateien hilft das Feld „Dateien suchen...“ oberhalb der Liste. Sind die Schaltflächen nicht sichtbar, ist Ihr Fenster zu schmal: Scrollen Sie in der Info-Box nach rechts oder ziehen Sie sie breiter.</p>',12),e("p",null,[e("video",{src:f,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/map_attachment.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),i('<h2 id="_3-8-exportformate-im-uberblick" tabindex="-1">3.8 Exportformate im Überblick <a class="header-anchor" href="#_3-8-exportformate-im-uberblick" aria-label="Permalink to &quot;3.8 Exportformate im Überblick&quot;">​</a></h2><p>Qonnectra hat keinen Menüpunkt „Export“. Daten verlassen die Anwendung dort, wo sie auch angezeigt werden, jeweils in dem Format, das zum Inhalt passt:</p><table tabindex="0"><thead><tr><th>Format</th><th>Wo</th><th>Inhalt</th></tr></thead><tbody><tr><td>Excel (<code>.xlsx</code>)</td><td>Rohrverwaltung, „Vorlage“</td><td>leere Importvorlage für Rohre, siehe Abschnitt <a href="./10-rohrverwaltung.html#_10-5-excel-import-vorlage-ablauf-fehlermeldungen">Excel-Import</a></td></tr><tr><td>Excel (<code>.xlsx</code>)</td><td>Netzknoten, „Slot-Konfiguration anzeigen“</td><td>Einbauplätze und Komponenten eines Netzknotens, siehe Abschnitt <a href="./05-karte.html#_5-6-netzknoten-slot-konfiguration-und-struktur-offnen">Netzknoten</a></td></tr><tr><td>CSV</td><td>Störungsanalyse, „CSV exportieren“</td><td>Schadensbericht mit den betroffenen Objekten, siehe Kapitel <a href="./06-stoerungsanalyse.html">Störungsanalyse</a></td></tr><tr><td>PDF</td><td>Adressdetails und Nachverdichtung, „PDF herunterladen“</td><td>Datenblatt zu einer Adresse, wahlweise mit den Wohneinheiten, siehe Kapitel <a href="./16-adressen.html">Adressen</a> und <a href="./07-nachverdichtung.html">Nachverdichtung</a></td></tr><tr><td>GeoJSON</td><td>Faserweg, „GeoJSON herunterladen“</td><td>Geometrien des ermittelten Faserwegs, siehe Kapitel <a href="./15-faserweg.html">Faserweg</a></td></tr><tr><td>ZIP</td><td>Leitungsauskunft, „Exportieren“</td><td>je Objektart eine GeoJSON-Datei, eine QGIS-Layerdatei (<code>.qlr</code>) und die Anhänge der enthaltenen Objekte, siehe Kapitel <a href="./08-leitungsauskunft.html">Leitungsauskunft</a></td></tr></tbody></table><p>Einzelne Dateien laden Sie über den Reiter „Anhänge“ herunter, siehe Abschnitt <a href="#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die CSV-Datei der Störungsanalyse ist kommagetrennt. Ein Doppelklick öffnet sie zwar in Excel, in deutscher Einstellung steht dann aber die ganze Zeile in einer Spalte. Öffnen Sie die Datei stattdessen über „Daten“ → „Aus Text/CSV“ und wählen Sie das Komma als Trennzeichen.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ganze Datenbestände tauscht die Administration über den Administrationsbereich und QGIS aus, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/24-daten-import-und-export.html">Daten importieren und exportieren</a>.</p></div>',6)])])}const E=r(k,[["render",S]]);export{A as __pageData,E as default};
